#include <iostream>
#include <string>
#include <string_view>
using namespace std;

int main() {
    string s = "cppmind:modern:cpp";

    string sub = s.substr(8, 6);              // 分配新 string（堆内存 + 拷贝）
    string_view sv(s.data() + 8, 6);          // 只存指针 + 长度，零拷贝

    cout << "substr     -> \"" << sub << "\"  (size=" << sub.size() << "，拥有内存)\n";
    cout << "string_view-> \"" << sv << "\"  (size=" << sv.size() << "，不拥有内存)\n";

    string_view tail = s;                     // 整个字符串的视图
    tail.remove_prefix(15);
    cout << "remove_prefix(15) 后 -> \"" << tail << "\"\n";

    cout << "\n注意：string_view 不延长被观察对象的生命周期。\n";
    cout << "string_view bad = string(\"temp\");  // 悬垂！临时 string 已析构\n";
    cout << "结论：string_view 适合作只读参数，不适合长期持有\n";
}
